TLM.f("Sancti/10-21cc",{"officium":"Ss. Ursulæ et Sociarum Virg. et Mart.","rule":["vide C6a;"],"ruleInherited":["Gloria"],"fallback":"Commune/C6a","from":{"Introitus":"Commune/C6a","Lectio":"Commune/C6a","Graduale":"Commune/C6a","GradualeP":"Commune/C6a","Tractus":"Commune/C6a","Evangelium":"Commune/C6a","Offertorium":"Commune/C6a","Communio":"Commune/C6a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:95-96"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Da nobis, quǽsumus, Dómine, Deus noster, sanctárum Vírginum et Mártyrum tuárum Ursulæ et Sociárum palmas incessábili devotióne venerári: ut, quas digna mente non póssumus celebráre, humílibus saltem frequentémus obséquiis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:13-17"},{"k":"text","la":"Dómine, Deus meus, exaltásti super terram habitatiónem meam, et pro morte defluénte deprecáta sum. Invocávi Dóminum, Patrem Dómini mei, ut non derelínquat me in die tribulatiónis meæ, et in témpore superbórum sine adjutório. Laudábo nomen tuum assídue, et collaudábo illud in confessióne, et exaudíta est orátio mea. Et liberásti me de perditióne, et eripuísti me de témpore iníquo. Proptérea confitébor et laudem dicam tibi, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 45:6; 45:5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis ímpetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est Virgo sápiens, et una de número prudéntum. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est Virgo sápiens, et una de número prudéntum.","mark":"V"},{"k":"ref","la":"Sap 4:1"},{"k":"text","la":"O quam pulchra et casta generátio cum claritáte! Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 45:6; 45:5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis ímpetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe corónam, quam tibi Dóminus præparávit in ætérnum: pro cujus amóre sánguinem tuum fudísti"},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"},{"k":"rubric","la":"Tempore paschali omittitur graduale."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Inténde, quǽsumus, Dómine, múnera altáribus tuis pro sanctárum Vírginum et Mártyrum tuárum Ursulæ et Sociárum festivitáte propósita: ut, sicut per hæc beáta mystéria illis glóriam contulísti; ita nobis indulgéntiam largiáris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:121; 118:122; 118:128"},{"k":"text","la":"Feci judícium et justítiam, Dómine, non calumniéntur mihi supérbi: ad ómnia mandáta tua dirigébar, omnem viam iniquitátis ódio hábui. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Praesta nobis, quaésumus, Dómine: intercedéntibus sanctis Martýribus tuis Ursula et Sociábus eius; ut, quod ore contíngimus, pura mente capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"db0c2103b5594b03":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine Bože naš, da pobjedničku slavu tvojih svetih mučenica Uršule i njezinih drugarica neprestano i pobožno štujemo, da im iskažemo čast barem našom poniznom službom, kad ih ne možemo dostojno slaviti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"eius → ∅","kn":"Podaj, molimoi, Gospodine, Bože naš, da pobjedu svetih Tvojih mučenicai, Perpetue i Felicitas, svetkujemo neprestanom pobožnošću, te što nismo dostojni vršiti, obavljamo' barem poniznom službom. Po G. n. I. K.","knRef":"Kniewald 1942, str. 518–519 (snimka 260) (OCR)"},"ff57b59fe1c39371":{"t":"Pogledaj, Gospodine, na darove što ih stavljamo na tvoje oltare o svetkovini tvojih blaženih mučenica Uršule i njezinih drugarica, da nam po ovim blaženim otajstvima udijeliš oproštenje kao što si njima udijelio slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"eius → ∅","kn":"Primi, Gospodine, darove, što Ti ih prinosimo o svetkovini blaženih mučenica Perpetue i Sv. Toma Akvinac 7. III. Felicitas, uzdajući se, da ćeš po ovim blaženim 'Otajstvima i nama udijeliti oproštenje, kao što si njima udijelio slavu. Po G. n. I. K.","knRef":"Kniewald 1942, str. 518–519 (snimka 260) (OCR)"},"89a993886f3286bc":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, po zagovoru svojih svetih mučenika Uršule i njezinih drugarica da čistom dušom prihvatimo što smo ustima primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, Gospodine, da zagovorom Tvojih svetih mučenika I. i I., čistom dušom prihvatimo, što ustima primamo, po G. n.","knRef":"Kniewald 1942, str. 806–807 (snimka 404) (OCR)"}}});
